import { useNavigate, useParams, useSearchParams, useLocation } from 'react-router-dom';
import { PLATFORMS, SECOND_PLATS, DAYS90, daily, fmtW, yuan, ME, TAGS, GENRES, LANGS, COVERS, platColor, Drama } from './mock';
