const sum = (a: number[]) => a.reduce((x, y) => x + y, 0);
const useMine = () => { const { S } = useS(); return useMemo(() => S.dramas.filter((d) => d.cust === ME), [S.dramas, S.account]); };
const STAGES = ['上传', '审核', '准备上架', '已上架', '有收益'];
export const StageBar = ({ d }: any) => { const s = stage(d.status) + (d.plays > 0 ? 1 : 0); const cs = clientStatus(d.status); return <Tooltip title={STAGES.map((x, i) => (i < s ? '✔ ' : '○ ') + x).join('  ')}><div className="stagebar">{STAGES.map((x, i) => <i key={x} style={{ background: i < s ? (cs === '需要你处理' && i === s - 1 ? '#fa8c16' : CS[cs]?.c === '#8c8c8c' && cs !== '已下架' ? '#bfbfbf' : CS[cs].c) : undefined }} />)}</div></Tooltip>; };
export const NotFound = ({ msg }: any) => { const nav = useNavigate(); const loc = useLocation(); const o = loc.pathname.startsWith('/o'); const a = loc.pathname.startsWith('/a'); return <div className="page"><Result status="404" title={msg || '页面不存在'} subTitle={o || a ? '链接可能已失效' : '链接可能已失效，或这部剧不属于当前账号'} extra={<Space><Button type="primary" onClick={() => nav(o ? '/o/workbench' : a ? '/a/roles' : '/u/library')}>{o ? '回运营工作台' : a ? '回管理端' : '回到我的剧集'}</Button><Button onClick={() => nav(-1)}>返回上一页</Button></Space>} /></div>; };

// ───────── 数据总览
export function Dashboard() {
  const nav = useNavigate(); const { S, up } = useS(); const mine = useMine(); const [range, setRange] = useState<any>(30); const [m, setM] = useState<'plays' | 'rev'>('plays'); const [tab, setTab] = useState('o');
  const live = mine.filter((d) => d.plays > 0); const days = DAYS90.slice(-range);
  const series = PLATFORMS.map((p, pi) => ({ name: p.key, color: p.color, data: days.map((_, i) => Math.round(sum(live.slice(pi * 7, pi * 7 + 40).map((d) => daily(d, range, m)[i])) * (1 - pi * 0.12))) }));
  const prevF = range === 7 ? 0.85 : range === 30 ? 0.91 : 0.8; const tot = sum(series.flatMap((s) => s.data)); const totP = m === 'plays' ? tot : sum(PLATFORMS.map((_, pi) => sum(days.map((_, i) => sum(live.slice(pi * 7, pi * 7 + 40).map((d) => daily(d, range, 'plays')[i]))))));
  const totR = m === 'rev' ? tot : Math.round(totP * 0.022);
  const top = [...live].sort((a, b) => b.plays - a.plays).slice(0, 10);
  const steps = [{ k: '企业认证', done: S.cert !== '未认证' && S.cert !== '认证驳回', to: '/u/account' }, { k: '上传剧集', done: S.uploaded || mine.length > 0, to: '/u/upload' }, { k: '申请发行', done: S.plans.some((p) => mine.some((d) => d.id === p.did)), to: '/u/library' }]; const doneN = steps.filter((s) => s.done).length;
  const platShare = PLATFORMS.map((p, i) => ({ name: p.key, value: sum(series[i].data), itemStyle: { color: p.color } }));
  const best = platShare.reduce((a, b) => (b.value > a.value ? b : a), platShare[0]);
  return <div className="page">
    <PH title="数据总览" icon={<FireFilled />} sub={<Space>数据更新到 10 月 20 日 <Tooltip title="各平台数据更新时间不同：ReelShort/DramaBox/FlexTV 更新到昨天，ShortMax/GoodShort 更新到前天"><a>为什么有的平台慢一天？</a></Tooltip><Demo /></Space>}
      extra={<><Segmented value={range} onChange={setRange} options={[{ label: '近7天', value: 7 }, { label: '近30天', value: 30 }, { label: '近90天', value: 90 }]} /><Button icon={<DownloadOutlined />} onClick={() => download(`数据总览_近${range}天.csv`, [['剧名', '剧ID', '播放量', '收益(人民币预估)'], ...live.map((d) => [d.cn, d.id, d.plays, d.rev])])}>导出</Button></>} />
    {doneN < 3 && <div className="card onboard"><div style={{ flex: 1 }}><div style={{ fontSize: 16, fontWeight: 600 }}>3 步开始发行 · 已完成 {doneN}/3</div><Progress percent={Math.round((doneN / 3) * 100)} strokeColor="#D6153C" style={{ maxWidth: 420 }} />
      <div className="obsteps">{steps.map((s, i) => <div key={s.k} className={'obs' + (s.done ? ' done' : '')} onClick={() => nav(s.to)}>{s.done ? <CheckCircleFilled /> : <span className="num">{i + 1}</span>}{s.k}</div>)}</div></div>
      <BigBtn onClick={() => nav(steps.find((s) => !s.done)!.to)}>下一步：{steps.find((s) => !s.done)!.k} <RightOutlined /></BigBtn></div>}
    {!live.length ? <div className="card" style={{ marginTop: 16 }}><Empty2 title={mine.length ? '剧还没上架，暂时没有数据' : '还没有数据'} desc={mine.length ? '上架后第二天早上就能在这里看到播放和收益' : '上传并发行第一部剧，上架后这里会显示每天的播放和收益'} action={<BigBtn onClick={() => nav(mine.length ? '/u/library' : '/u/upload')}>{mine.length ? '去申请发行' : '上传第一部剧'}</BigBtn>} /></div> : <>
    <Tabs activeKey={tab} onChange={setTab} items={[{ key: 'o', label: '总览' }, { key: 'd', label: '剧集数据' }, { key: 'p', label: '平台对比' }]} />
    {tab === 'o' && <Row gutter={[16, 16]}>
      <Col span={24}><Conclusion>近 {range} 天播放量较前 {range} 天 <b className="up">+{Math.round((1 / prevF - 1) * 100)}%</b>，增长最多的是《{top[0]?.cn}》在 {best.name}；{best.name} 贡献了 {Math.round((best.value / tot) * 100)}% 的{m === 'plays' ? '播放' : '收益'}。</Conclusion></Col>
      {[['总播放量', fmtW(totP), Math.round((1 / prevF - 1) * 100), <PlayCircleFilled />, '#D6153C'], ['收益（人民币预估）', yuan(totR), Math.round((1 / prevF - 1) * 80), <DollarCircleFilled />, '#18864b', '按当前汇率估算，最终以结算单为准'], ['在架剧集', live.length + ' 部', null, <VideoCameraFilled />, '#1668dc'], ['发行平台', S.platforms.filter((p) => p.on && live.some((d) => d.plats[p.key] === '已上架')).length + ' 家', null, <GlobalOutlined />, '#7c4dff']].map(([a, b, c, ic, co, t]: any) =>
        <Col span={6} key={a}><Kpi label={a} value={b} delta={c} icon={ic} color={co} tip={t} /></Col>)}
      <Col span={16}><div className="card"><div className="ct"><Space>趋势<span className="syncb">{PLATFORMS.map((p) => <Tooltip key={p.key} title={<div><b>{p.key} · {p.sync}</b><div>{p.sync === 'T-1' ? '每天早上 6 点前更新到昨天' : '平台出数慢，每天更新到前天'}（当前：10月{p.sync === 'T-1' ? 20 : 19}日）</div></div>}><span className="sb" style={{ borderColor: p.color, color: p.color }}>{p.short} {p.sync}</span></Tooltip>)}</span></Space><Segmented size="small" value={m} onChange={setM as any} options={[{ label: '播放量', value: 'plays' }, { label: '收益', value: 'rev' }]} /></div>
        <Chart height={300} option={{ xAxis: { type: 'category', data: days, boundaryGap: false }, yAxis: { type: 'value', axisLabel: { formatter: (v: number) => (m === 'rev' ? '¥' : '') + v / 1e4 + '万' } }, series: series.map((s) => ({ name: s.name, type: 'line', smooth: true, showSymbol: false, stack: 't', areaStyle: { opacity: 0.08 }, lineStyle: { width: 2 }, color: s.color, data: s.data })) }} /></div></Col>
      <Col span={8}><div className="card"><div className="ct">平台占比</div><Chart height={300} option={{ tooltip: { trigger: 'item' }, legend: { bottom: 0, left: 'center' }, series: [{ type: 'pie', radius: ['48%', '72%'], center: ['50%', '44%'], label: { show: false }, data: platShare }] }} /></div></Col>
      <Col span={24}><div className="card"><div className="ct">Top 10 剧（点击海报看详情）<span className="meta">按播放量</span></div>
        <div className="topwall">{top.map((d, i) => <div key={d.id} className="topcard" onClick={() => nav('/u/drama/' + d.id)}><div className="rank">{i + 1}</div><Cover d={d} h={150} /><div className="nm ell">{d.cn}</div><div className="meta">{fmtW(d.plays)} 播放</div><Progress percent={Math.round((d.plays / top[0].plays) * 100)} showInfo={false} size="small" strokeColor="#D6153C" /></div>)}</div></div></Col>
      <Col span={24}><Collapse items={[{ key: '1', label: '查看明细（剧 × 平台）', children: <DetailTable live={live} /> }]} /></Col>
    </Row>}
    {tab === 'd' && <DramaData live={live} />}
    {tab === 'p' && <Row gutter={[16, 16]}>{PLATFORMS.map((p, i) => <Col span={24 / 5 > 4 ? 5 : 4} flex="20%" key={p.key}><div className="card platcard"><PlatLogo k={p.key} size={40} /><div style={{ fontWeight: 600, marginTop: 8 }}>{p.key}</div><div className="v">{fmtW(sum(series[i].data))}</div><div className="meta">{m === 'plays' ? '播放' : '收益'} · 数据更新到 10月{p.sync === 'T-1' ? 20 : 19}日</div><Progress percent={Math.round((sum(series[i].data) / best.value) * 100)} showInfo={false} strokeColor={p.color} /></div></Col>)}
      <Col span={24}><div className="card"><Conclusion>{best.name} 是你最赚钱的平台；GoodShort 增速最快，可以考虑把更多新剧投放过去。</Conclusion><Chart height={300} option={{ xAxis: { type: 'category', data: PLATFORMS.map((p) => p.key) }, yAxis: { type: 'value' }, series: [{ type: 'bar', barWidth: 36, data: platShare.map((x) => ({ value: x.value, itemStyle: { color: x.itemStyle.color, borderRadius: [8, 8, 0, 0] } })) }] }} /></div></Col></Row>}
  </>}</div>;
}
function DetailTable({ live }: any) {
  const rows = live.flatMap((d: Drama) => PLATFORMS.filter((p) => d.plats[p.key] === '已上架').map((p, i) => ({ k: d.id + p.key, d, plat: p.key, plays: Math.round(d.plays / (2 + i)), rev: Math.round(d.rev / (2 + i)) })));
  return <Table size="small" rowKey="k" dataSource={rows} pagination={pager(rows.length)} columns={[{ title: '剧', render: (r: any) => <Space><Cover d={r.d} h={40} w={30} ep={false} />{r.d.cn}</Space>, sorter: (a: any, b: any) => a.d.cn.localeCompare(b.d.cn) }, { title: '平台', dataIndex: 'plat', render: (k: string) => <Space><PlatLogo k={k} />{k}</Space>, filters: PLATFORMS.map((p) => ({ text: p.key, value: p.key })), onFilter: (v: any, r: any) => r.plat === v }, { title: '播放', dataIndex: 'plays', render: fmtW, sorter: (a: any, b: any) => a.plays - b.plays }, { title: '收益(预估)', dataIndex: 'rev', render: yuan, sorter: (a: any, b: any) => a.rev - b.rev }]} />;
}
function DramaData({ live }: any) {
  const [q, setQ] = useState(''); const [plat, setPlat] = useState<string[]>([]); const [days, setDays] = useState(7); const [pg, setPg] = useState({ c: 1, s: 20 });
  const ds = live.filter((d: Drama) => !q || d.cn.includes(q) || d.id.includes(q)); const ps = PLATFORMS.filter((p) => !plat.length || plat.includes(p.key));
  const total = ds.length * ps.length * days; const start = (pg.c - 1) * pg.s;
  const page = Array.from({ length: Math.max(0, Math.min(pg.s, total - start)) }, (_, j) => { const i = start + j; const di = i % days, pi = Math.floor(i / days) % ps.length, d = ds[Math.floor(i / days / ps.length)]; const v = daily(d, days, 'plays')[di]; return { k: i, d, plat: ps[pi].key, day: DAYS90[90 - days + di], plays: Math.round(v / (1 + pi)), done: Math.round((d.done - pi * 0.03) * 100), rev: Math.round((v / (1 + pi)) * 0.022) }; });
  return <div className="card"><Space wrap style={{ marginBottom: 16 }}><Input.Search placeholder="剧名 / 剧 ID" allowClear onSearch={(v) => { setQ(v); setPg({ ...pg, c: 1 }); }} style={{ width: 240 }} /><Select mode="multiple" placeholder="全部平台" style={{ minWidth: 220 }} value={plat} onChange={(v) => { setPlat(v); setPg({ ...pg, c: 1 }); }} options={PLATFORMS.map((p) => ({ value: p.key, label: p.key }))} /><Segmented value={days} onChange={(v: any) => setDays(v)} options={[{ label: '近7天', value: 7 }, { label: '近30天', value: 30 }]} />
    <Button icon={<DownloadOutlined />} onClick={() => download('剧集数据.csv', [['剧', '平台', '日期', '播放', '完播率', '收益'], ...page.map((r) => [r.d.cn, r.plat, r.day, r.plays, r.done + '%', r.rev])])}>导出</Button></Space>
    <Table size="small" rowKey="k" dataSource={page} pagination={{ ...pager(total), current: pg.c, pageSize: pg.s, onChange: (c, s) => setPg({ c, s }) }} columns={[{ title: '剧', render: (r: any) => <Space><Cover d={r.d} h={40} w={30} ep={false} /><span className="ell" style={{ maxWidth: 260, display: 'inline-block' }}>{r.d.cn}</span></Space> }, { title: '平台', dataIndex: 'plat', render: (k: string) => <Space><PlatLogo k={k} />{k}</Space> }, { title: '日期', dataIndex: 'day' }, { title: '播放量', dataIndex: 'plays', render: fmtW }, { title: '完播率', dataIndex: 'done', render: (v: number) => <Progress percent={v} size="small" style={{ width: 120 }} /> }, { title: '收益(预估)', dataIndex: 'rev', render: yuan }]} /></div>;
}

// ───────── 我的剧集（封面墙）
const STATUS_CARDS = ['全部', '需要你处理', '审核中', '准备上架', '已上架', '草稿'];
export function Library() {
  const nav = useNavigate(); const { S, up, undoable } = useS(); const { message } = App.useApp(); const mine = useMine();
  const [f, setF] = useState<any>({ st: '全部' }); const [q, setQ] = useState(''); const [quick, setQuick] = useState<string[]>([]); const [mode, setMode] = useState<any>('wall'); const [sort, setSort] = useState('up');
  const [pg, setPg] = useState({ c: 1, s: 24 }); const [sel, setSel] = useState<Set<string>>(new Set()); const [adv, setAdv] = useState(false); const [view, setView] = useState('默认'); const [pub, setPub] = useState<string[] | null>(null); const [dragOver, setDragOver] = useState('');
  const r1 = useRef(null), r2 = useRef(null), r3 = useRef(null), r4 = useRef(null);
  const counts = useMemo(() => { const c: any = { 全部: mine.length }; mine.forEach((d) => { const k = clientStatus(d.status); c[k] = (c[k] || 0) + 1; }); return c; }, [mine]);
  const list = useMemo(() => { let l = mine.filter((d) => {
    if (f.st && f.st !== '全部' && clientStatus(d.status) !== f.st) return false;
    if (q && !(d.cn.includes(q) || d.en.toLowerCase().includes(q.toLowerCase()) || d.id.includes(q.toUpperCase()))) return false;
    if (f.group && !d.groups.includes(f.group)) return false; if (f.genre?.length && !f.genre.includes(d.genre)) return false; if (f.lang?.length && !f.lang.includes(d.lang)) return false;
    if (f.epMin && d.eps < f.epMin) return false; if (f.epMax && d.eps > f.epMax) return false; if (f.rej && d.problems === 0) return false; if (f.nolic && d.lic) return false;
    for (const k of quick) { if (k === '首发' || k === '二轮') { if (d.round !== k) return false; } else if (k === '近7天') { if (d.up < '2026-10-14') return false; } else if (k.startsWith('#')) { if (!d.tags.includes(k.slice(1))) return false; } else if (d.plats[k] !== '已上架') return false; }
    return true; });
    return l.sort((a, b) => sort === 'up' ? b.up.localeCompare(a.up) : sort === 'plays' ? b.plays - a.plays : sort === 'name' ? a.cn.localeCompare(b.cn, 'zh') : b.eps - a.eps); }, [mine, f, q, quick, sort]);
  useEffect(() => setPg((p) => ({ ...p, c: 1 })), [f, q, quick]);
  const page = list.slice((pg.c - 1) * pg.s, pg.c * pg.s);
  const toggle = (id: string) => { const n = new Set(sel); n.has(id) ? n.delete(id) : n.add(id); setSel(n); };
  const setTags = (tag: string) => { const ids = [...sel]; const before = new Map(S.dramas.filter((d) => sel.has(d.id)).map((d) => [d.id, d.tags])); undoable(`已为 ${ids.length} 部打上「${tag}」`, () => up((n) => { n.dramas = n.dramas.map((d) => sel.has(d.id) && !d.tags.includes(tag) ? { ...d, tags: [...d.tags, tag] } : d); }), () => up((n) => { n.dramas = n.dramas.map((d) => before.has(d.id) ? { ...d, tags: before.get(d.id)! } : d); })); };
  const addGroup = (g: string, ids: string[]) => { const set = new Set(ids); undoable(`已把 ${ids.length} 部加入「${g}」`, () => up((n) => { if (!n.groups.includes(g)) n.groups = [...n.groups, g]; n.dramas = n.dramas.map((d) => set.has(d.id) && !d.groups.includes(g) ? { ...d, groups: [...d.groups, g] } : d); }), () => up((n) => { n.dramas = n.dramas.map((d) => set.has(d.id) ? { ...d, groups: d.groups.filter((x) => x !== g) } : d); })); };
  const chips: any[] = []; if (f.st !== '全部') chips.push(['st', '状态：' + f.st]); if (f.group) chips.push(['group', '分组：' + f.group]); if (f.genre?.length) chips.push(['genre', '题材：' + f.genre.join('/')]); if (f.lang?.length) chips.push(['lang', '语言：' + f.lang.join('/')]); if (f.epMin || f.epMax) chips.push(['ep', `集数 ${f.epMin || 0}-${f.epMax || '∞'}`]); if (f.rej) chips.push(['rej', '有需修改的集']); if (f.nolic) chips.push(['nolic', '缺授权书']); quick.forEach((k) => chips.push(['q:' + k, k.replace('#', '标签：')])); if (q) chips.push(['kw', '搜索：' + q]);
  const rmChip = (k: string) => { if (k.startsWith('q:')) setQuick(quick.filter((x) => x !== k.slice(2))); else if (k === 'kw') setQ(''); else if (k === 'ep') setF({ ...f, epMin: undefined, epMax: undefined }); else setF({ ...f, [k]: k === 'st' ? '全部' : undefined }); };
  const applyView = (name: string) => { setView(name); const v = S.views.find((x) => x.name === name); setF({ st: '全部', ...(v?.f || {}) }); setQuick(v?.quick || []); setQ(v?.q || ''); if (v?.mode) setMode(v.mode); };
  return <div className="page lib">
    <PH title="我的剧集" icon={<VideoCameraFilled />} sub={<Space>共 {mine.length} 部 · 点卡片左上角可多选，批量申请发行 <Demo /></Space>} extra={<><span ref={r4}><Segmented value={mode} onChange={setMode} options={[{ value: 'wall', icon: <AppstoreOutlined />, label: '封面墙' }, { value: 'table', icon: <BarsOutlined />, label: '表格' }]} /></span><span ref={r1}><BigBtn icon={<CloudUploadOutlined />} onClick={() => nav('/u/upload')}>批量上传</BigBtn></span></>} />
    <Tabs size="small" activeKey={view} onChange={applyView} className="viewtabs" items={[{ key: '默认', label: '全部剧集' }, ...S.views.map((v) => ({ key: v.name, label: <span>{v.name} <CloseOutlined className="vx" onClick={(e) => { e.stopPropagation(); up((n) => { n.views = n.views.filter((x) => x.name !== v.name); }); if (view === v.name) applyView('默认'); }} /></span> }))]}
      tabBarExtraContent={<Button size="small" type="text" icon={<SaveOutlined />} onClick={() => { let name = '我的视图 ' + (S.views.length + 1); Modal.confirm({ title: '保存当前筛选为视图', icon: <SaveOutlined />, content: <Input defaultValue={name} onChange={(e) => (name = e.target.value)} />, onOk: () => { up((n) => { n.views = [...n.views, { name, f, quick, q, mode }]; }); setView(name); message.success('视图已保存，以页签显示'); } }); }}>保存为视图</Button>} />
    <div className="stcards" ref={r2}>{STATUS_CARDS.map((k) => { const c = CS[k] || { c: '#0f0f0f', bg: 'var(--soft)', i: <AppstoreOutlined /> }; return <div key={k} className={'stcard' + (f.st === k ? ' on' : '')} style={{ ['--c' as any]: c.c }} onClick={() => setF({ ...f, st: k })}><span className="sic" style={{ background: c.bg, color: c.c }}>{c.i}</span><div><div className="n">{counts[k] || 0}</div><div className="l">{k}</div></div></div>; })}</div>
    <div className="quick"><Input.Search placeholder="剧名 / 外文名 / 剧 ID" allowClear style={{ width: 210 }} onSearch={setQ} />
      {['首发', '二轮', '近7天'].map((k) => <Tag.CheckableTag key={k} checked={quick.includes(k)} onChange={(c) => setQuick(c ? [...quick, k] : quick.filter((x) => x !== k))}>{k}</Tag.CheckableTag>)}
      {PLATFORMS.map((p) => <Tag.CheckableTag key={p.key} checked={quick.includes(p.key)} onChange={(c) => setQuick(c ? [...quick, p.key] : quick.filter((x) => x !== p.key))}><Tooltip title={'只看已在 ' + p.key + ' 上架'}><span><PlatLogo k={p.key} size={18} title={false} /></span></Tooltip></Tag.CheckableTag>)}
      {TAGS.slice(0, 2).map((t) => <Tag.CheckableTag key={t.k} checked={quick.includes('#' + t.k)} onChange={(c) => setQuick(c ? [...quick, '#' + t.k] : quick.filter((x) => x !== '#' + t.k))}>#{t.k}</Tag.CheckableTag>)}
      <span style={{ flex: 1 }} /><Select size="middle" value={sort} onChange={setSort} style={{ width: 130 }} options={[{ value: 'up', label: '最近上传' }, { value: 'plays', label: '播放最多' }, { value: 'name', label: '剧名' }, { value: 'eps', label: '集数最多' }]} /><Button icon={<FilterOutlined />} onClick={() => setAdv(true)}>更多筛选</Button></div>
    {chips.length > 0 && <div className="chips">{chips.map(([k, l]) => <Tag key={k} closable onClose={(e) => { e.preventDefault(); rmChip(k); }} color="red" bordered={false}>{l}</Tag>)}<a onClick={() => { setF({ st: '全部' }); setQuick([]); setQ(''); }}>清空</a><span className="meta">· 找到 {list.length} 部</span></div>}
    <div className="libbody">
      <div className="groups"><div className="gt">分组 <Tooltip title="把封面拖到分组上即可归组"><span className="meta">拖拽归组</span></Tooltip></div>
        {[{ k: '', n: '全部剧集' }, ...S.groups.map((g) => ({ k: g, n: g }))].map((g) => { const ds = g.k ? mine.filter((d) => d.groups.includes(g.k)) : mine; return <div key={g.k} className={'grp' + ((f.group || '') === g.k ? ' on' : '') + (dragOver === g.k && g.k ? ' over' : '')} onClick={() => setF({ ...f, group: g.k || undefined })}
          onDragOver={(e) => { if (g.k) { e.preventDefault(); setDragOver(g.k); } }} onDragLeave={() => setDragOver('')} onDrop={(e) => { setDragOver(''); const id = e.dataTransfer.getData('id'); addGroup(g.k, sel.has(id) ? [...sel] : [id]); }}>
          <div className="mosaic">{ds.slice(0, 4).map((d) => <img key={d.id} src={COVERS[d.img]} />)}</div><div style={{ minWidth: 0 }}><div className="ell">{g.n}</div><div className="meta">{ds.length} 部</div></div></div>; })}
        <Button type="dashed" block icon={<PlusOutlined />} onClick={() => { let name = ''; Modal.confirm({ title: '新建分组', icon: <FolderAddOutlined />, content: <Input placeholder="例如：2027 Q1 新剧" onChange={(e) => (name = e.target.value)} />, onOk: () => { if (!name.trim()) { message.warning('请输入分组名'); return Promise.reject(); } up((n) => { n.groups = [...n.groups, name.trim()]; }); } }); }}>新建分组</Button></div>
      <div style={{ flex: 1, minWidth: 0 }}>
        {list.length === 0 && !mine.length ? <Empty2 title="还没有剧" desc="把整个文件夹拖进来，系统自动识别剧名和集号" action={<BigBtn icon={<CloudUploadOutlined />} onClick={() => nav('/u/upload')}>批量上传</BigBtn>} /> : list.length === 0 ? <Empty2 title="没有符合条件的剧" desc="换个筛选条件试试，或者上传新剧" action={<Space><Button onClick={() => { setF({ st: '全部' }); setQuick([]); setQ(''); }}>清空筛选</Button><Button type="primary" onClick={() => nav('/u/upload')}>批量上传</Button></Space>} /> :
          mode === 'wall' ? <div className="wall">{page.map((d, i) => <div key={d.id} className={'vcard' + (sel.has(d.id) ? ' sel' : '') + (sel.size ? ' selmode' : '')} draggable onDragStart={(e) => e.dataTransfer.setData('id', d.id)} onClick={() => (sel.size ? toggle(d.id) : nav('/u/drama/' + d.id))}>
            <div style={{ position: 'relative' }}><Cover d={d} h={230} /><span className="ck" ref={i === 0 ? r3 : undefined} onClick={(e) => { e.stopPropagation(); toggle(d.id); }}><Checkbox checked={sel.has(d.id)} /></span><span className="cbadge"><CStatus raw={d.status} /></span>
</div>
            <div className="nm" title={d.cn}>{d.cn}</div><StageBar d={d} />
            <div className="meta" style={{ display: 'flex', justifyContent: 'space-between' }}><span>{d.round} · {d.genre}</span><span>{d.plays ? <><PlayCircleFilled /> {fmtW(d.plays)}</> : d.up.slice(5)}</span></div>
            <div className="tagrow">{Object.entries(d.plats).slice(0, 6).map(([k, v]) => <PlatLogo key={k} k={k} size={18} dim={v !== '已上架'} />)}
            {d.tags.slice(0, 2).map((t) => <Tag key={t} bordered={false} color={TAGS.find((x) => x.k === t)?.c}>{t}</Tag>)}</div></div>)}</div>
            : <Table rowKey="id" size="middle" dataSource={page} pagination={false} rowSelection={{ selectedRowKeys: [...sel], onChange: (k) => setSel(new Set(k as string[])) }} onRow={(r) => ({ onClick: () => nav('/u/drama/' + r.id), style: { cursor: 'pointer' } })} columns={[{ title: '剧', render: (d: Drama) => <Space><Cover d={d} h={56} w={42} ep={false} /><div><div style={{ fontWeight: 600 }}>{d.cn}</div><div className="meta">{d.id} · {d.en}</div></div></Space> }, { title: '状态', render: (d: Drama) => <CStatus raw={d.status} /> }, { title: '进度', render: (d: Drama) => <StageBar d={d} /> }, { title: '集数', dataIndex: 'eps' }, { title: '轮次', dataIndex: 'round' }, { title: '平台', render: (d: Drama) => <Space size={2}>{Object.entries(d.plats).map(([k, v]) => <PlatLogo key={k} k={k} size={18} dim={v !== '已上架'} />)}</Space> }, { title: '播放', render: (d: Drama) => d.plays ? fmtW(d.plays) : '—' }, { title: '上传', dataIndex: 'up' }]} />}
        {list.length > 0 && <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 20 }}><Pagination current={pg.c} pageSize={pg.s} total={list.length} showSizeChanger pageSizeOptions={[24, 48, 96]} onChange={(c, s) => setPg({ c, s })} showTotal={(t) => `共 ${t} 部`} /></div>}
      </div></div>
    {sel.size > 0 && <div className="floatbar"><b>已选 {sel.size} 部</b>{sel.size < list.length && <a onClick={() => setSel(new Set(list.map((d) => d.id)))}>选中全部筛选结果（共 {list.length} 部）</a>}
      <BigBtn icon={<SendOutlined />} onClick={() => setPub([...sel])}>申请发行</BigBtn>
      <Dropdown menu={{ items: TAGS.map((t) => ({ key: t.k, label: <Tag color={t.c} bordered={false}>{t.k}</Tag> })), onClick: ({ key }) => setTags(key) }}><Button icon={<TagsOutlined />}>打标签</Button></Dropdown>
      <Dropdown menu={{ items: S.groups.map((g) => ({ key: g, label: g, icon: <FolderFilled /> })), onClick: ({ key }) => addGroup(key, [...sel]) }}><Button icon={<FolderAddOutlined />}>加入分组</Button></Dropdown>
      <Button icon={<DownloadOutlined />} onClick={() => { download(`剧集导出_${sel.size}部.csv`, [['剧ID', '剧名', '外文名', '状态', '集数', '轮次', '题材', '标签'], ...S.dramas.filter((d) => sel.has(d.id)).map((d) => [d.id, d.cn, d.en, clientStatus(d.status), d.eps, d.round, d.genre, d.tags.join('/')])]); message.success('已导出 ' + sel.size + ' 部'); }}>导出</Button>
      <Button type="text" onClick={() => setSel(new Set())}>取消选择</Button></div>}
    <Drawer title="更多筛选" open={adv} onClose={() => setAdv(false)} width={400} extra={<Button type="primary" onClick={() => setAdv(false)}>完成</Button>}>
      <Form layout="vertical"><Form.Item label="题材"><Select mode="multiple" value={f.genre} onChange={(v) => setF({ ...f, genre: v })} options={GENRES.map((g) => ({ value: g, label: g }))} /></Form.Item>
        <Form.Item label="语言"><Select mode="multiple" value={f.lang} onChange={(v) => setF({ ...f, lang: v })} options={['英语', ...LANGS].filter((x, i, a) => a.indexOf(x) === i).map((g) => ({ value: g, label: g }))} /></Form.Item>
        <Form.Item label="集数区间"><Space><InputNumber placeholder="最少" value={f.epMin} onChange={(v) => setF({ ...f, epMin: v })} /> ~ <InputNumber placeholder="最多" value={f.epMax} onChange={(v) => setF({ ...f, epMax: v })} /></Space></Form.Item>
        <Form.Item label="分组"><Select allowClear value={f.group} onChange={(v) => setF({ ...f, group: v })} options={S.groups.map((g) => ({ value: g, label: g }))} /></Form.Item>
        <Checkbox checked={f.rej} onChange={(e) => setF({ ...f, rej: e.target.checked })}>只看有需修改的集</Checkbox><br /><br /><Checkbox checked={f.nolic} onChange={(e) => setF({ ...f, nolic: e.target.checked })}>只看缺授权书的剧</Checkbox></Form>
      <Alert style={{ marginTop: 24 }} type="info" showIcon message={`当前条件下有 ${list.length} 部`} /></Drawer>
    {pub && <PublishWizard ids={pub} onClose={(done?: boolean) => { setPub(null); if (done) setSel(new Set()); }} />}
    <Tour open={S.firstVisit.library} onClose={() => { localStorage.setItem('tour_lib', '1'); up((n) => { n.firstVisit = { ...n.firstVisit, library: false }; }); }} indicatorsRender={(c, t) => <span>{c + 1}/{t} <a style={{ marginLeft: 8 }} onClick={() => { localStorage.setItem('tour_lib', '1'); up((n) => { n.firstVisit = { ...n.firstVisit, library: false }; }); }}>跳过全部</a></span>} steps={[{ title: '先把剧传上来', description: '整个文件夹拖进来，系统自动识别剧名和集号', target: () => r1.current as any }, { title: '点卡片即筛选', description: '橙色「需要你处理」的剧最优先', target: () => r2.current as any }, { title: '勾选多部剧', description: '勾选后底部出现操作条，一次申请发行几百部', target: () => r3.current as any }, { title: '封面墙 / 表格随时切', target: () => r4.current as any }]} />
  </div>;
}

// ───────── 发行申请向导（单部/批量统一）
export function PublishWizard({ ids, onClose, round: r0 }: any) {
  const { S, up, addTask } = useS(); const nav = useNavigate(); const [step, setStep] = useState(0); const [list, setList] = useState<string[]>(ids); const [round, setRound] = useState(r0 || ''); const [plats, setPlats] = useState<string[]>([]); const [other, setOther] = useState(''); const [res, setRes] = useState<any>(null);
  const ds = S.dramas.filter((d) => list.includes(d.id));
  const licOk = S.licenses.some((l: any) => l.status === '已通过'); const check = (d: Drama) => { if (!d.lic) return { ok: false, why: licOk ? '缺授权书' : S.licenses.length ? '授权书审核中' : '缺授权书', fix: '/u/account' }; if (['上传中', '校验中'].includes(d.status)) return { ok: false, why: '还在上传' }; if (d.status === '校验失败') return { ok: false, why: '有视频文件不合格', fix: '/u/drama/' + d.id };
    if (round === '首发') { if (!['草稿', '已撤回'].includes(d.status)) return { ok: false, why: clientStatus(d.status) === '需要你处理' ? '需先修改问题集' : '已经申请过首发', fix: '/u/drama/' + d.id }; } else { if (d.status !== '发行中') return { ok: false, why: '首发上架后才能申请二轮' }; } return { ok: true }; };
  const pre = ds.map((d) => ({ d, ...check(d) })); const okN = pre.filter((p) => p.ok).length;
  const submit = () => { const okIds = pre.filter((p) => p.ok).map((p) => p.d.id); const batch = 'PC-' + nid(); const pl = round === '首发' ? S.platforms.filter((p) => p.first && p.on).map((p) => p.key) : [...plats, ...(other ? other.split(/[,，]/) : [])];
    up((n) => { n.dramas = n.dramas.map((d) => okIds.includes(d.id) ? { ...d, status: '待分派', round, submitted: now() } : d); n.plans = [...okIds.map((id, i) => ({ id: 'FX-' + nid(), did: id, round, plats: pl, batch, time: now(), status: '进行中', eta: '10月23日', mine: true })), ...n.plans]; });
    addTask({ name: `批量发行申请 · ${okIds.length} 部`, total: pre.length, icon: <SendOutlined />, run: () => ({ ok: okIds.length, fail: pre.length - okIds.length, report: pre.map((p) => ({ ok: p.ok, m: `《${p.d.cn}》${p.ok ? '已提交' : '未提交：' + p.why}` })) }) });
    setRes({ ok: okIds.length, bad: pre.filter((p) => !p.ok) }); };
  const canNext = [list.length > 0 && !!round && (round === '首发' || plats.length > 0 || !!other.trim()), okN > 0][step];
  return <Modal open width={980} title={<Space><SendOutlined />申请发行</Space>} onCancel={() => onClose(!!res)} footer={res ? null : <Space><Button onClick={() => (step ? setStep(step - 1) : onClose())}>{step ? '上一步' : '取消'}</Button>{step < 1 ? <Button type="primary" disabled={!canNext} onClick={() => setStep(step + 1)}>下一步：检查</Button> : <Button type="primary" size="large" disabled={!okN} onClick={submit}>提交 {okN} 部</Button>}</Space>}>
    {res ? <Result status="success" title={`已提交 ${res.ok} 部${res.bad.length ? `，${res.bad.length} 部需处理` : ''}`} subTitle="我们会在 10 月 23 日前完成审核，进度可在「发行进度」随时查看"
      extra={[<Button key="a" type="primary" onClick={() => { onClose(true); nav('/u/plans'); }}>查看发行进度</Button>, <Button key="b" onClick={() => onClose(true)}>继续管理剧集</Button>]}>{res.bad.length > 0 && <div className="prelist">{res.bad.slice(0, 8).map((p: any) => <div key={p.d.id} className="pre bad"><Cover d={p.d} h={48} w={36} ep={false} /><span className="ell" style={{ flex: 1 }}>{p.d.cn}</span><Tag color="orange">{p.why}</Tag>{p.fix && <a onClick={() => { onClose(true); nav(p.fix); }}>去处理</a>}</div>)}</div>}</Result> : <>
      <Steps current={step} size="small" style={{ margin: '8px 0 24px' }} items={[{ title: '选剧与发行方式' }, { title: '检查并提交' }]} />
      {step === 0 && <><div className="meta" style={{ marginBottom: 12 }}>已选 {list.length} 部（单次最多 200 部），点 × 可移除</div><div className="miniwall">{ds.slice(0, 60).map((d) => <div key={d.id} className="mini"><Cover d={d} h={120} /><Button className="rm" size="small" shape="circle" icon={<CloseOutlined />} onClick={() => setList(list.filter((x) => x !== d.id))} /><div className="ell meta">{d.cn}</div></div>)}{ds.length > 60 && <div className="mini more">+{ds.length - 60}</div>}</div>
      <Row gutter={16} style={{ marginTop: 16 }}>{[['首发', <RocketFilled />, '第一次发行'], ['二轮', <GlobalOutlined />, '已上架的剧，再发往更多平台']].map(([k, ic, t]: any) => <Col span={12} key={k}><div className={'pick' + (round === k ? ' on' : '')} onClick={() => setRound(k)} style={{ display: 'flex', gap: 12, alignItems: 'center', textAlign: 'left' }}><div className="pic" style={{ margin: 0 }}>{ic}</div><div style={{ flex: 1 }}><div style={{ fontSize: 18, fontWeight: 600 }}>{k}</div><div className="meta">{t}</div>{k === '首发' && <Space size={4} style={{ marginTop: 6 }}>{S.platforms.filter((p) => p.first && p.on).map((p) => <Tooltip key={p.key} title={p.key}><span><PlatLogo k={p.key} size={22} /></span></Tooltip>)}<span className="meta">自动发往这 5 家</span></Space>}</div></div></Col>)}</Row></>}
      {step === 0 && round === '二轮' && (<><div style={{ height: 16 }} /><Alert type="info" showIcon style={{ marginBottom: 12 }} message={<span>这些剧已在 {[...new Set(ds.flatMap((d) => Object.keys(d.plats).filter((k) => d.plats[k] === '已上架')))].join('、') || '—'} 上架；下面选新的平台（统一应用到所有已选剧）</span>} /><div className="platpick">{S.platforms.filter((p) => !p.first && p.on).map((p) => <div key={p.key} className={'pp' + (plats.includes(p.key) ? ' on' : '')} onClick={() => setPlats(plats.includes(p.key) ? plats.filter((x) => x !== p.key) : [...plats, p.key])}><PlatLogo k={p.key} size={44} /><b>{p.key}</b><span className="meta">{p.region}</span>{plats.includes(p.key) && <CheckCircleFilled className="pk" />}</div>)}</div><Input style={{ marginTop: 16 }} placeholder="其他平台（用逗号分隔，提交后商务补录）" value={other} onChange={(e) => setOther(e.target.value)} /></>)}
      {step === 1 && <><Space size={24} style={{ marginBottom: 16 }}><span className="bignum ok"><CheckCircleFilled /> {okN} 部可以提交</span><span className="bignum warn"><ExclamationCircleFilled /> {pre.length - okN} 部需处理（不影响其他剧）</span></Space>
        <div className="prelist">{pre.map((p) => <div key={p.d.id} className={'pre' + (p.ok ? '' : ' bad')}><Cover d={p.d} h={48} w={36} ep={false} /><span className="ell" style={{ flex: 1 }}>{p.d.cn}</span>{p.ok ? <Tag color="success" icon={<CheckCircleFilled />}>可提交</Tag> : <><Tag color="warning" icon={<ExclamationCircleFilled />}>{p.why}</Tag>{p.fix && <a onClick={() => { onClose(); nav(p.fix!); }}>去处理</a>}</>}</div>)}</div></>}
    </>}
  </Modal>;
}

// ───────── 发行进度（发行计划列表）
export function Plans() {
  const { S, up, undoable } = useS(); const nav = useNavigate(); const [q, setQ] = useState(''); const [st, setSt] = useState('全部'); const [sel, setSel] = useState<string[]>([]);
  const rows = S.plans.filter((p) => S.dramas.find((x) => x.id === p.did)?.cust === ME).map((p) => { const d = S.dramas.find((x) => x.id === p.did)!; const cs = p.status === '已撤回' ? '已下架' : clientStatus(d.status); return { ...p, d, cs, canW: p.status !== '已撤回' && ['待分派', '待审核', '预检中'].includes(d.status) }; }).filter((r) => r.d && (st === '全部' || r.cs === st || (st === '已撤回' && r.status === '已撤回')) && (!q || r.d.cn.includes(q) || r.batch.includes(q) || r.id.includes(q)));
  const withdraw = (ids: string[]) => { const ps = S.plans.filter((p) => ids.includes(p.id)); const prev = new Map(ps.map((p) => [p.did, S.dramas.find((d) => d.id === p.did)!.status]));
    undoable(`已撤回 ${ids.length} 个申请`, () => up((n) => { n.plans = n.plans.map((p) => ids.includes(p.id) ? { ...p, status: '已撤回' } : p); n.dramas = n.dramas.map((d) => prev.has(d.id) ? { ...d, status: '已撤回' } : d); }), () => up((n) => { n.plans = n.plans.map((p) => ids.includes(p.id) ? { ...p, status: '进行中' } : p); n.dramas = n.dramas.map((d) => prev.has(d.id) ? { ...d, status: prev.get(d.id)! } : d); })); setSel([]); };
  const cnt = (k: string) => S.plans.filter((p) => { const d = S.dramas.find((x) => x.id === p.did); return d && (p.status === '已撤回' ? '已下架' : clientStatus(d.status)) === k; }).length;
  return <div className="page"><PH title="发行进度" icon={<SendOutlined />} sub="每部剧的每次发行申请都在这里，审核开始前可以撤回" extra={<BigBtn icon={<SendOutlined />} onClick={() => nav('/u/library')}>去选剧申请发行</BigBtn>} />
    <div className="stcards">{['全部', '需要你处理', '审核中', '准备上架', '已上架', '已下架'].map((k) => <div key={k} className={'stcard' + (st === k ? ' on' : '')} onClick={() => setSt(k)}><span className="sic" style={{ background: CS[k]?.bg || 'var(--soft)', color: CS[k]?.c }}>{CS[k]?.i || <AppstoreOutlined />}</span><div><div className="n">{k === '全部' ? S.plans.length : cnt(k)}</div><div className="l">{k === '已下架' ? '已撤回/下架' : k}</div></div></div>)}</div>
    <div className="card" style={{ padding: 16 }}><Space style={{ marginBottom: 12 }}><Input.Search allowClear placeholder="剧名 / 批次号 / 申请号" onSearch={setQ} style={{ width: 280 }} />{sel.length > 0 && <Button danger icon={<RollbackOutlined />} onClick={() => withdraw(sel)}>撤回所选 {sel.length} 个</Button>}</Space>
      <Table rowKey="id" dataSource={rows} pagination={pager(rows.length)} rowSelection={{ selectedRowKeys: sel, onChange: (k) => setSel(k as string[]), getCheckboxProps: (r: any) => ({ disabled: !r.canW }) }}
        columns={[{ title: '剧', width: 320, render: (r: any) => <Space style={{ cursor: 'pointer' }} onClick={() => nav('/u/drama/' + r.did)}><Cover d={r.d} h={56} w={42} ep={false} /><div style={{ minWidth: 0 }}><b className="ell" style={{ display: 'block', maxWidth: 240 }}>{r.d.cn}</b><div className="meta">{r.id} · 批次 {r.batch}</div></div></Space> },
          { title: '类型', dataIndex: 'round', render: (v: string) => <Tag color={v === '首发' ? 'red' : 'purple'}>{v}</Tag>, filters: [{ text: '首发', value: '首发' }, { text: '二轮', value: '二轮' }], onFilter: (v: any, r: any) => r.round === v },
          { title: '平台', render: (r: any) => <Space size={2}>{r.plats.map((k: string) => <PlatLogo key={k} k={k} size={18} />)}</Space> },
          { title: '进度', width: 200, render: (r: any) => r.status === '已撤回' ? <CStatus s="已下架" /> : <div><CStatus s={r.cs} /><div style={{ marginTop: 6, width: 160 }}><StageBar d={r.d} /></div></div> },
          { title: '预计完成', width: 120, render: (r: any) => r.cs === '审核中' ? <span style={{ whiteSpace: 'nowrap' }}><ClockCircleFilled style={{ color: '#1668dc' }} /> {r.eta}前</span> : '—' }, { title: '提交时间', width: 150, dataIndex: 'time', sorter: (a: any, b: any) => a.time.localeCompare(b.time), defaultSortOrder: 'descend' },
          { title: '', render: (r: any) => r.canW ? <Button size="small" icon={<RollbackOutlined />} onClick={() => withdraw([r.id])}>撤回</Button> : r.cs === '需要你处理' ? <Button size="small" type="primary" ghost onClick={() => nav('/u/drama/' + r.did + '?tab=eps')}>去修改</Button> : null }]} /></div></div>;
}

// ───────── 剧详情
export function DramaDetail() {
  const { id } = useParams(); const [sp] = useSearchParams(); const nav = useNavigate(); const { S, up, addTask } = useS(); const { message } = App.useApp(); const d = S.dramas.find((x) => x.id === id && x.cust === ME);
  const [tab, setTab] = useState(sp.get('tab') || 'data'); const [grp, setGrp] = useState(0); const [pub, setPub] = useState<any>(null); const [replaced, setReplaced] = useState<number[]>([]);
  if (!d) return <NotFound msg="这部剧不存在" />;
  const cs = clientStatus(d.status); const live = d.plays > 0; const probEps = d.problems ? Array.from({ length: d.problems }, (_, i) => [12, 27, 58][i] % d.eps) : [];
  const plans = S.plans.filter((p) => p.did === d.id); const tickets = S.tickets.filter((t) => t.did === d.id);
  const back = () => (window.history.length > 2 ? nav(-1) : nav('/u/library'));
  const primary = cs === '草稿' ? <BigBtn icon={<SendOutlined />} onClick={() => setPub([d.id])}>申请发行</BigBtn> : cs === '需要你处理' && d.lic ? <BigBtn icon={<SwapOutlined />} onClick={() => setTab('eps')}>修改 {d.problems || ''} 集并重新提交</BigBtn> : !d.lic ? <BigBtn onClick={() => setTab('lic')}>补授权书</BigBtn> : cs === '已上架' ? <BigBtn icon={<GlobalOutlined />} onClick={() => setPub([d.id])} >申请二轮发行</BigBtn> : null;
  const resubmit = () => { up((n) => { n.dramas = n.dramas.map((x) => x.id === d.id ? { ...x, status: '待审核', problems: 0, resub: x.resub + 1 } : x); }); message.success('已重新提交，只会复审替换过的集'); setReplaced([]); };
  const ser = DAYS90.slice(-30); const dp = daily(d, 30, 'plays');
  return <div className="page">
    <Button type="text" icon={<ArrowLeftOutlined />} onClick={back} style={{ marginBottom: 8 }}>返回</Button>
    <div className="card dhead"><Cover d={d} h={220} w={165} />
      <div style={{ flex: 1, minWidth: 0 }}><Space><CStatus raw={d.status} big />{d.tags.map((t) => <Tag key={t} bordered={false} color={TAGS.find((x) => x.k === t)?.c}>{t}</Tag>)}</Space>
        <h1 style={{ margin: '10px 0 4px', fontSize: 26 }}>{d.cn}</h1><div className="meta">{d.en} · {d.id} · {d.eps} 集 · {d.genre} · {d.lang} · {d.round}</div>
        <Steps style={{ marginTop: 24, maxWidth: 720 }} size="small" current={Math.min(4, stage(d.status) + (live ? 1 : 0) - 1)} status={cs === '需要你处理' ? 'error' : undefined} items={STAGES.map((t, i) => ({ title: t, description: i === 1 && cs === '审核中' ? '预计 10月23日前' : i === 1 && cs === '需要你处理' ? '有问题待修改' : undefined }))} /></div>
      <div>{primary}</div></div>
    <Tabs activeKey={tab} onChange={setTab} style={{ marginTop: 16 }} items={[{ key: 'data', label: '数据' }, { key: 'eps', label: <Badge count={d.problems} size="small" offset={[8, 0]}>剧集</Badge> }, { key: 'plan', label: `发行记录 (${plans.length})` }, { key: 'plat', label: '各平台' }, { key: 'lic', label: <span>授权与素材 {!d.lic && <ExclamationCircleFilled style={{ color: '#fa8c16' }} />}</span> }, { key: 'tk', label: `相关消息 (${tickets.length})` }]} />
    {tab === 'data' && (live ? <Row gutter={[16, 16]}><Col span={24}><Conclusion>近 30 天《{d.cn}》共 {fmtW(sum(dp))} 次播放，完播率 {Math.round(d.done * 100)}%，表现最好的平台是 {Object.keys(d.plats).find((k) => d.plats[k] === '已上架')}。</Conclusion></Col>
      {[['总播放', fmtW(d.plays), <PlayCircleFilled />], ['收益(预估)', yuan(d.rev), <DollarCircleFilled />], ['完播率', Math.round(d.done * 100) + '%', <EyeOutlined />], ['已上架平台', Object.values(d.plats).filter((v) => v === '已上架').length + ' 家', <GlobalOutlined />]].map(([a, b, ic]: any) => <Col span={6} key={a}><Kpi label={a} value={b} icon={ic} /></Col>)}
      <Col span={24}><div className="card"><div className="ct">近 30 天播放</div><Chart height={260} option={{ xAxis: { type: 'category', data: ser }, yAxis: { type: 'value' }, series: [{ type: 'bar', data: dp, itemStyle: { color: '#D6153C', borderRadius: [4, 4, 0, 0] } }] }} /></div></Col></Row>
      : <Empty2 title={cs === '已下架' ? '这部剧已下架或已撤回' : '上架后，这里会显示播放和收益'} desc={cs === '草稿' ? '现在申请发行，最快 3 天上架' : cs === '审核中' ? '正在审核，预计 10 月 23 日前完成' : cs === '准备上架' ? '已通过审核，正在和平台对接上架' : cs === '需要你处理' ? '有几集需要修改，修改后重新提交' : ''} action={primary} />)}
    {tab === 'eps' && <div className="card">
      {d.problems > 0 && <Alert type="warning" showIcon style={{ marginBottom: 16 }} message={<b>{d.problems} 集需要修改：{probEps.map((e) => `第${e}集`).join('、')}</b>} description="原因：字幕错位 / 片头含第三方水印。替换视频后点「重新提交」，只复审替换过的集。"
        action={<Space direction="vertical"><Upload showUploadList={false} multiple beforeUpload={() => { setReplaced(probEps); message.success('已替换 ' + probEps.length + ' 集'); return false; }}><Button>一键替换</Button></Upload><Button type="primary" disabled={replaced.length < probEps.length} onClick={resubmit}>重新提交</Button></Space>} />}
      {d.eps > 50 && <Segmented style={{ marginBottom: 16 }} value={grp} onChange={(v: any) => setGrp(v)} options={Array.from({ length: Math.ceil(d.eps / 50) }, (_, i) => ({ value: i, label: `第 ${i * 50 + 1}-${Math.min(d.eps, i * 50 + 50)} 集` }))} />}
      <div className="epwall">{Array.from({ length: Math.min(50, d.eps - grp * 50) }, (_, i) => { const e = grp * 50 + i + 1; const bad = probEps.includes(e) && !replaced.includes(e); const rep = replaced.includes(e); const sampled = d.checked > 0 && (e <= 3 || e > d.eps - 2 || e % 10 === 5);
        return <Tooltip key={e} title={bad ? '需修改：字幕错位' : rep ? '已替换，待复审' : sampled ? '抽查通过' : '文件正常'}><div className={'epc' + (bad ? ' bad' : rep ? ' rep' : '')} style={{ backgroundImage: `url(${COVERS[(d.img + e) % 6]})`, backgroundPosition: `${(e * 37) % 100}% ${(e * 53) % 100}%` }}><span>{e}</span>{bad ? <CloseCircleFilled className="eb" /> : rep ? <SwapOutlined className="eb" /> : sampled ? <CheckCircleFilled className="eb ok" /> : null}</div></Tooltip>; })}</div></div>}
    {tab === 'plan' && (plans.length ? <div className="card">{plans.map((p) => <div key={p.id} className="planrow"><Tag color={p.round === '首发' ? 'red' : 'purple'}>{p.round}</Tag><span className="meta">{p.id} · {p.time}</span><Space size={2}>{p.plats.map((k: string) => <PlatLogo key={k} k={k} size={20} />)}</Space><span style={{ flex: 1 }} />{p.status === '已撤回' ? <CStatus s="已下架" /> : <CStatus raw={d.status} />}</div>)}</div> : <Empty2 title="还没有发行申请" action={primary} />)}
    {tab === 'plat' && (Object.keys(d.plats).length ? <div className="platpick">{Object.entries(d.plats).map(([k, v]) => { const c = v === '已上架' ? CS['已上架'] : v === '平台已拒绝' ? { c: '#d6153c', bg: '#fde8ec', i: <CloseCircleFilled /> } : v === '已下架' ? CS['已下架'] : CS['准备上架']; return <div key={k} className="pp" style={{ cursor: 'default' }}><PlatLogo k={k} size={44} /><b>{k}</b><span className="cst" style={{ color: c.c, background: c.bg }}>{c.i}{v === '已上架' ? '已上架' : v === '平台已拒绝' ? '平台未接收' : v === '已下架' ? '已下架' : '准备上架'}</span>{v === '已上架' && <a className="meta" onClick={() => setTab('tk')}>查看上架截图</a>}</div>; })}</div> : <Empty2 title="还没有发往任何平台" desc="审核通过后，这里会显示每个平台的上架进度" action={primary} />)}
    {tab === 'lic' && <div className="card"><Row gutter={24}><Col span={12}><div className="ct">授权书 / 版权证明</div>{d.lic ? <Alert type="success" showIcon message="已关联「2026 年度片库授权书.pdf」" /> : <><Alert type="warning" showIcon message="还没有关联授权书，不能申请发行" style={{ marginBottom: 12 }} /><Space wrap>{!S.licenses.some((l: any) => l.status === '已通过') && <Alert type="info" showIcon message={S.licenses.length ? '授权书运营审核中，通过后即可关联' : '先去账户中心上传授权书'} action={<Button size="small" onClick={() => nav('/u/account')}>去账户中心</Button>} />}{S.licenses.filter((l: any) => l.status === '已通过').map((l) => <Button key={l.id} onClick={() => { up((n) => { n.dramas = n.dramas.map((x) => x.id === d.id ? { ...x, lic: true, status: x.status === '待补资质' ? '草稿' : x.status } : x); }); message.success('已关联 ' + l.name); }}>关联 {l.name}</Button>)}</Space></>}</Col>
      <Col span={12}><div className="ct">素材</div><div className="assets">{[['封面', 1], ['海报', 1], ['预告片', 1], ['字幕', d.lang === '英语' ? 1 : 0]].map(([k, ok]: any) => <div key={k} className="asset">{ok ? <CheckCircleFilled style={{ color: '#18864b' }} /> : <ExclamationCircleFilled style={{ color: '#fa8c16' }} />}<span>{k}</span></div>)}</div></Col></Row></div>}
    {tab === 'tk' && (tickets.length ? <div className="card">{tickets.map((t) => <div key={t.id} className="planrow" style={{ cursor: 'pointer' }} onClick={() => nav('/u/tickets?id=' + t.id)}><ST s={t.type} /><b className="ell" style={{ flex: 1 }}>{t.title}</b><span className="meta">{t.time}</span></div>)}</div> : <Empty2 title="暂无相关消息" />)}
    {pub && <PublishWizard ids={pub} round={cs === '已上架' ? '二轮' : '首发'} onClose={() => setPub(null)} />}
  </div>;
}

// ───────── 批量上传
export function BatchUpload() {
  const { S, up } = useS(); const nav = useNavigate(); const { message } = App.useApp(); const [items, setItems] = useState<any[]>([]); const [open, setOpen] = useState<string | null>(null); const [done, setDone] = useState(0); const [meta, setMeta] = useState(false);
  const parse = (files: any[]) => { const g: Record<string, any> = {}; files.forEach((f) => { const p = (f.webkitRelativePath || f.name).split('/'); const name = p.length > 2 ? p[1] : p.length === 2 ? p[0] : '未命名剧'; const fn = p[p.length - 1]; const m = fn.match(/(\d+)/); g[name] = g[name] || { name, eps: new Set(), extra: [], cover: false, sub: false };
    if (/cover|poster/i.test(fn)) g[name].cover = true; else if (/\.srt$/i.test(fn)) g[name].sub = true; else if (/\.(mp4|mov|mkv)$/i.test(fn) && m) g[name].eps.add(+m[1]); else g[name].extra.push(fn); });
    return Object.values(g).map((x: any) => ({ id: nid('U'), name: x.name, total: x.eps.size ? Math.max(...x.eps) : 0, got: x.eps.size, missing: x.eps.size ? Math.max(...x.eps) - x.eps.size : 0, extra: x.extra.length, conflict: 0, cover: x.cover, sub: x.sub, ok: false })); };
  const demo = () => setItems([{ id: nid('U'), name: '总裁的契约娇妻', total: 80, got: 80, missing: 0, extra: 0, conflict: 0, cover: true, sub: true }, { id: nid('U'), name: '战神赘婿', total: 96, got: 94, missing: 2, extra: 0, conflict: 0, cover: true, sub: false }, { id: nid('U'), name: '穿越之农门医女', total: 72, got: 72, missing: 0, extra: 3, conflict: 0, cover: false, sub: true }, { id: nid('U'), name: '我的天才萌宝', total: 60, got: 61, missing: 0, extra: 0, conflict: 1, cover: true, sub: true }, { id: nid('U'), name: '豪门弃妇的逆袭', total: 88, got: 88, missing: 0, extra: 0, conflict: 0, cover: true, sub: true }].map((x) => ({ ...x, ok: false })));
  const issue = (x: any) => x.conflict ? ['red', `${x.conflict} 个集号冲突`] : x.missing ? ['orange', `缺 ${x.missing} 集`] : x.extra ? ['default', `${x.extra} 个多余文件`] : null;
  const confirm = (sel: any[]) => { const created = sel.map((x, i) => ({ ...S.dramas[0], id: 'D' + (90000 + S.dramas.length + i), cn: x.name, en: '', eps: x.total, status: '上传中', tags: ['2026Q4'], groups: [], up: '2026-10-21', cust: ME, img: (i + 2) % 6, tint: i % 7, lic: true, round: '首发', plats: {}, plays: 0, rev: 0, done: 0, problems: 0, checked: 0 }));
    up((n) => { n.dramas = [...created, ...n.dramas]; n.uploads = [...created.map((d, i) => ({ id: nid('Q'), did: d.id, name: d.cn, files: d.eps + 2, p: 0, status: '排队中', fail: i === 1 })), ...n.uploads]; n.uploaded = true; });
    setItems(items.filter((x) => !sel.includes(x))); setDone(done + sel.length); message.success(`${sel.length} 部已加入上传队列，可以离开本页`); };
  const okItems = items.filter((x) => !issue(x));
  return <div className="page"><PH title="批量上传" icon={<CloudUploadOutlined />} sub="把整个文件夹拖进来，系统自动认出剧名和集号" extra={<><Button icon={<FileExcelOutlined />} onClick={() => download('元数据模板.csv', [['剧名*', '语言*', '集数*', '外文名', '题材', '简介', '标签', '授权书编号'], ['总裁的契约娇妻', '英语', 80, 'The Contract Wife', '甜宠', '', '女频', 'SQ-001']])}>下载元数据模板</Button><Upload showUploadList={false} accept=".csv,.xlsx" beforeUpload={() => { setMeta(true); message.success('元数据已导入，已按剧名与文件夹匹配'); return false; }}><Button icon={<FileExcelOutlined />}>{meta ? '✔ 已导入元数据' : '导入元数据 Excel（可选）'}</Button></Upload></>} />
    {!items.length && <div className="how">{[['📁', '按「剧名/第001集.mp4」整理文件夹'], ['🖱️', '整个文件夹拖进下面的框'], ['✅', '确认识别结果，开始上传']].map(([i, t], k) => <div key={k} className="howc"><div className="hi">{i}</div><div><b>第 {k + 1} 步</b><div className="meta">{t}</div></div>{k < 2 && <RightOutlined className="ha" />}</div>)}</div>}
    <Upload.Dragger multiple directory showUploadList={false} beforeUpload={(f, fl) => { if (f === fl[0]) { const r = parse(fl as any); setItems([...items, ...r]); message.success(`识别出 ${r.length} 部剧`); } return false; }} className="bigdrag">
      <p style={{ fontSize: 56, color: '#D6153C', margin: 0 }}><FolderOpenOutlined /></p><p style={{ fontSize: 18, fontWeight: 600 }}>把文件夹拖到这里，或点击选择文件夹</p><p className="meta">支持一次多部剧 · 第001集.mp4 / EP01.mp4 / 01.mp4 都能识别 · cover.jpg 自动作为封面 · 断点续传</p></Upload.Dragger>
    <div style={{ textAlign: 'center', margin: '12px 0 24px' }}><Button type="link" onClick={demo}>没有文件？用示例文件夹体验一下</Button>{done > 0 && <span className="meta">本次已加入上传 {done} 部 · <a onClick={() => nav('/u/library')}>去我的剧集查看</a></span>}</div>
    {items.length > 0 && <><div className="ct" style={{ fontSize: 18 }}><span>识别结果：{items.length} 部剧 <span className="meta">· {okItems.length} 部没问题</span></span><Space><Button onClick={() => setItems([])}>清空</Button><BigBtn disabled={!okItems.length} icon={<CheckCircleFilled />} onClick={() => confirm(okItems)}>确认 {okItems.length} 部，开始上传</BigBtn></Space></div>
      <div className="matchwall">{items.map((x, i) => { const is = issue(x); return <div key={x.id} className={'mcard' + (is ? ' ' + is[0] : '')} onClick={() => setOpen(open === x.id ? null : x.id)}>
        <div style={{ display: 'flex', gap: 12 }}><div className="mcov" style={{ backgroundImage: x.cover ? `url(${COVERS[(i + 2) % 6]})` : undefined }}>{!x.cover && '无封面'}</div><div style={{ flex: 1, minWidth: 0 }}><b className="ell" style={{ display: 'block' }}>{x.name}</b><div className="meta">{x.got}/{x.total} 集已匹配</div>{is ? <Tag color={is[0] === 'default' ? undefined : is[0]} style={{ marginTop: 6 }}>{is[1]}</Tag> : <Tag color="success" style={{ marginTop: 6 }} icon={<CheckCircleFilled />}>可以上传</Tag>}</div><Ring p={x.total ? Math.min(100, Math.round(((x.got - x.conflict) / x.total) * 100)) : 0} size={52} /></div>
        <div className="mchk">{[['信息', !!x.name], ['分集', !x.missing && !x.conflict], ['封面', !!x.cover], ['字幕', i % 3 !== 1]].map(([k, ok]: any) => <span key={k} className={ok ? 'ok' : 'no'}>{ok ? '✔' : '✖'} {k}</span>)}</div>
        {open === x.id && is && <div className="mfix" onClick={(e) => e.stopPropagation()}>{x.missing > 0 && <Space><span>缺第 {x.total - 1}、{x.total} 集</span><Upload showUploadList={false} multiple beforeUpload={() => { setItems(items.map((y) => y.id === x.id ? { ...y, got: y.total, missing: 0 } : y)); return false; }}><Button size="small" type="primary">补传</Button></Upload><Button size="small" onClick={() => setItems(items.map((y) => y.id === x.id ? { ...y, total: y.got, missing: 0 } : y))}>按 {x.got} 集上传</Button></Space>}
          {x.extra > 0 && <Space><span>{x.extra} 个无法识别的文件</span><Button size="small" onClick={() => setItems(items.map((y) => y.id === x.id ? { ...y, extra: 0 } : y))}>忽略</Button></Space>}
          {x.conflict > 0 && <Space><span>第 12 集有 2 个文件</span><Button size="small" onClick={() => setItems(items.map((y) => y.id === x.id ? { ...y, conflict: 0, got: y.total } : y))}>保留较新的</Button></Space>}</div>}</div>; })}</div></>}
  </div>;
}
